scorer.self_check:
if v, err := Calc("add", 1, 2); err != nil || v != 3 { panic("add=" + fmt.Sprint(v, err)) }
if v, err := Calc("sub", 5, 3); err != nil || v != 2 { panic("sub=" + fmt.Sprint(v, err)) }
if v, err := Calc("mul", 4, 3); err != nil || v != 12 { panic("mul=" + fmt.Sprint(v, err)) }
if v, err := Calc("div", 10, 4); err != nil || v != 2.5 { panic("div=" + fmt.Sprint(v, err)) }
if _, err := Calc("div", 1, 0); err == nil { panic("div-by-zero must error") }
if _, err := Calc("exp", 1, 2); err == nil { panic("unknown op must error") }
